    while j<W:
        if inp[H-1][j]==0: j+=1; continue
        kk=j
        while kk<W and inp[H-1][kk]!=0: kk+=1
        if kk-j>=2: R.append(list(inp[H-1][j:kk]))
        j=kk
    out=[list(r) for r in inp]
    for i in range(H):
        for j,v in enumerate(out[i]):
            if v==0: continue
            hit=False
            for seq in R:
                if v not in seq: continue
                s=j-seq.index(v)
                # keep even if partially outside: write only in-bounds cells
                for x in range(max(0,s),min(W,max(s,len(seq)-1))+max(0,len(seq)+len(seq)) ):
                    pass
                # simpler: write positions s..s+len-1, skipping those outside
                for x in range(s,s+len(seq)):
                    if 0<=x<W: out[i][x]=seq[x-s]
                hit=True;break
            if not hit:
                out[i][j]=0
    return out
